import {BEAST_HP} from './chapter-two-wildlife.js';
import {C2_STAGES} from './chapter-two-quest.js';
const regions={road:[2000,190,250],city:[2400,224,244],inn:[2800,160,200],manor:[3200,190,230]};
export function validateChapterTwo(s,require,finite,vector,actor){const q=s.chapter?.chapterTwo;if(q!==undefined){require(q&&C2_STAGES.includes(q.stage)&&[null,'rescue','tail'].includes(q.route));for(const k of ['roadOpen','courierFreed'])require(typeof q[k]==='boolean');for(const k of ['scouts','seals'])require(['idle','active','return','done'].includes(q[k]));if(s.chapter.p.stage==='chapter_two')require(q.stage!=='sleep')}const c=s.chapterTwo;if(c===undefined){require(s.chapter.p.stage!=='chapter_two');return}require(c&&[null,...Object.keys(regions)].includes(c.mode)&&Array.isArray(c.built)&&c.built.length<=4&&new Set(c.built).size===c.built.length&&c.built.every(k=>Object.hasOwn(regions,k))&&finite(c.time,0)&&finite(c.cartProgress,0,1)&&typeof c.cartAlerted==='boolean');if(c.mode){require(c.built.includes(c.mode)&&s.chapter.p.stage==='chapter_two'&&!s.world.inside&&!s.cemetery?.inside&&!s.chapel?.inside&&!s.dungeon?.mode&&!s.ritual?.mode&&!s.admin?.enabled);const [x,w,h]=regions[c.mode],pos=s.player.position;require(Math.abs(pos[0]-x)<w/2&&pos[2]>-h&&pos[2]<0)}if(c.origin)require(vector(c.origin.position)&&finite(c.origin.yaw)&&finite(c.origin.pitch,-1.35,1.35));require(Array.isArray(c.actors)&&c.actors.length<=45);const ids=new Set();for(const n of c.actors){actor(n.actor);require(c.built.includes(n.zone)&&['sword','mage','crossbow','warden','vampire'].includes(n.role)&&Number.isInteger(n.level)&&n.level>=11&&n.level<=17&&/^c2-(road-[0-5]|inn-[0-4]|manor-[0-7]|vampire|vampire-add-[01]|farm-(road|inn|manor)-[0-2]|raid-\d+-[0-5])$/.test(n.actor.id)&&!ids.has(n.actor.id));require(vector(n.actor.home));ids.add(n.actor.id);const hp=n.role==='vampire'?780:n.role==='warden'?290:n.role==='mage'?115:n.role==='crossbow'?105:135;require(n.actor.maxHp===hp&&finite(n.actor.hp,0,hp));for(const k of ['windup','specialReady','blockReady','blockLeft','shieldLeft','phase'])require(finite(n[k],0,20));require(typeof n.addsUsed==='boolean'&&['normal','pool','dash','drain'].includes(n.pending));const [x,w,h]=regions[n.zone];require(Math.abs(n.actor.position[0]-x)<w/2&&n.actor.position[2]>-h&&n.actor.position[2]<0)}for(const zone of c.built){const expected=zone==='road'?6:zone==='inn'?5:zone==='manor'?9:0;require(c.actors.filter(n=>n.zone===zone&&!['boss-add','farm','raid'].includes(n.group)).length===expected)}if(c.fauna){require(Array.isArray(c.fauna.actors)&&c.fauna.actors.length<=60);for(const n of c.fauna.actors){actor(n.actor);require(['road','inn','manor'].includes(n.zone)&&c.built.includes(n.zone)&&Object.hasOwn(BEAST_HP,n.species)&&n.actor.id.startsWith('c2-fauna-'+n.zone+'-'+n.species+'-')&&!ids.has(n.actor.id)&&vector(n.actor.home)&&Math.abs(n.actor.position[0]-regions[n.zone][0])<regions[n.zone][1]/2&&n.actor.position[2]>-regions[n.zone][2]&&n.actor.position[2]<0&&n.actor.maxHp===BEAST_HP[n.species]&&finite(n.actor.hp,0,n.actor.maxHp)&&finite(n.windup,0,1)&&finite(n.special,0,9)&&typeof n.lunge==='boolean'&&typeof n.slam==='boolean');ids.add(n.actor.id)}}if(c.raid){require(finite(c.raid.time,0,60.1)&&Number.isInteger(c.raid.minutes)&&c.raid.minutes>=0&&Number.isInteger(c.raid.serial)&&c.raid.serial>=0&&typeof c.raid.active==='boolean');require(c.actors.filter(n=>n.group==='raid').length<=6)}require(Array.isArray(c.lanterns)&&[0,3].includes(c.lanterns.length)&&c.lanterns.every(b=>typeof b==='boolean'));require(Array.isArray(c.chests)&&c.chests.length<=4&&c.chests.every(c=>['road-cache','city-cache','inn-cache','manor-cache'].includes(typeof c==='string'?c:c.id)));for(const chest of c.chests)if(typeof chest!=='string'){require(typeof chest.opened==='boolean'&&(chest.contents===null||Array.isArray(chest.contents)&&chest.contents.length<=3));for(const item of chest.contents||[])require(['gold','health_potion','mana_potion','cult_sign'].includes(item.id)&&Number.isInteger(item.count)&&item.count>0&&item.count<=30)}require(Array.isArray(c.drops)&&c.drops.length<=2000);for(const d of c.drops)require(['gold','cult_sign','vampire_signet','carcass','fang','bear_hide','werewolf_claw'].includes(d.id)&&c.built.includes(d.zone)&&vector(d.position)&&finite(d.phase)&&Number.isInteger(d.count)&&d.count>0&&d.count<=60);const b=c.combat;require(b&&finite(b.time,0)&&Array.isArray(b.shots)&&b.shots.length<=100&&Array.isArray(b.pools)&&b.pools.length<=15&&Array.isArray(b.tells)&&b.tells.length<=15);if(!c.mode)require(!b.shots.length&&!b.pools.length&&!b.tells.length);b.shots.forEach(p=>{require(vector(p.position)&&vector(p.velocity)&&finite(p.age,0,5)&&finite(p.damage,0,40)&&typeof p.arrow==='boolean'&&typeof p.ice==='boolean'&&typeof p.life==='boolean'&&ids.has(p.owner)&&finite(p.level,11,17))});b.pools.forEach(p=>require(vector(p.position)&&finite(p.age,0,7.1)&&finite(p.exposure,0,1.1)));b.tells.forEach(p=>require(vector(p.position)&&finite(p.age,0,1.2)))}
export function validateChapterTwoCheckpoint(cp,require,vector){const fires={c2_road:[[1991.2,-65],[1962.2,-195]],c2_city:[[2383.2,-39]],c2_inn:[[2823.2,-58],[2754.2,-43]],c2_manor:[[3186.2,-40],[3130.2,-43]]};require(fires[cp.zone]&&cp.id==='c2-'+cp.zone.slice(3)&&vector(cp.position)&&fires[cp.zone].some(f=>Math.hypot(cp.position[0]-f[0],cp.position[2]-f[1])<.2)&&cp.position[1]===1.7)}
